/**
 * frontend/src/components/CameraRecognition.jsx
 * Version finale - Structure propre, gestion d'erreurs détaillée, design minimal
 */

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { attendanceAPI } from './api_service';

const CAPTURE_INTERVAL_DEFAULT = 1500;
const CAPTURE_INTERVAL_FAST = 600;
const CONFIDENCE_THRESHOLD = 0.5;

const COLORS = {
  primary: '#2563EB',
  success: '#16A34A',
  danger: '#DC2626',
  warning: '#D97706',
  gray: '#64748B',
  border: '#E2E8F0',
  background: '#F8FAFC',
  text: '#0F172A',
};

const CameraRecognition = ({ addNotification }) => {
  const videoRef = useRef(null);
  const overlayCanvasRef = useRef(null);
  const streamRef = useRef(null);
  const timeoutRef = useRef(null);

  const [cameraActive, setCameraActive] = useState(false);
  const [autoMode, setAutoMode] = useState(false);
  const [loading, setLoading] = useState(false);
  const [status, setStatus] = useState('idle'); // idle, scanning, success, warning, error

  const [capturedImage, setCapturedImage] = useState(null);
  const [registeredPhotoUrl, setRegisteredPhotoUrl] = useState(null);
  const [lastResult, setLastResult] = useState(null);
  const [faceBox, setFaceBox] = useState(null);

  const [successCount, setSuccessCount] = useState(0);
  const [errorCount, setErrorCount] = useState(0);
  const [frameCount, setFrameCount] = useState(0);
  const [lastDetectionTime, setLastDetectionTime] = useState(null);
  const [errorMsg, setErrorMsg] = useState(null);
  const [errorDetails, setErrorDetails] = useState(null);

  // ====================== AUDIO FEEDBACK ======================
  const playSound = useCallback((type) => {
    try {
      const ctx = new (window.AudioContext || window.webkitAudioContext)();
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();

      if (type === 'success') {
        osc.type = 'sine';
        osc.frequency.setValueAtTime(800, ctx.currentTime);
        setTimeout(() => osc.frequency.setValueAtTime(1250, ctx.currentTime + 0.1), 80);
        gain.gain.value = 0.25;
      } else {
        osc.type = 'sawtooth';
        osc.frequency.setValueAtTime(420, ctx.currentTime);
        gain.gain.value = 0.2;
      }

      const filter = ctx.createBiquadFilter();
      filter.type = 'lowpass';
      filter.frequency.value = 2000;

      osc.connect(filter).connect(gain).connect(ctx.destination);
      osc.start();

      setTimeout(() => {
        gain.gain.linearRampToValueAtTime(0.001, ctx.currentTime + 0.35);
        osc.stop(ctx.currentTime + 0.45);
      }, type === 'success' ? 300 : 200);
    } catch (e) {
      console.warn('Audio non disponible');
    }
  }, []);

  // ====================== DÉMARRAGE CAMÉRA ======================
  const startCamera = async () => {
    try {
      setErrorMsg(null);
      setErrorDetails(null);
      setLoading(true);

      console.log('[CAMERA] Demande d\'accès à la caméra...');

      const stream = await navigator.mediaDevices.getUserMedia({
        video: { facingMode: "user" },
        audio: false,
      });

      streamRef.current = stream;

      if (videoRef.current) {
        videoRef.current.srcObject = stream;

        videoRef.current.onloadedmetadata = async () => {
          console.log('[CAMERA] Vidéo prête');
          setCameraActive(true);
          setLoading(false);

          try {
            await videoRef.current.play();
            console.log('[CAMERA] Lecture vidéo démarrée');
          } catch (playErr) {
            console.warn('[CAMERA] Lecture manuelle requise', playErr);
          }

          setAutoMode(true);
          if (addNotification) addNotification('Caméra démarrée avec succès', 'success');
        };
      }
    } catch (err) {
      console.error('[CAMERA ERROR]', err);
      const msg = err.name === 'NotAllowedError' ? 'Accès à la caméra refusé' 
                : err.name === 'NotFoundError' ? 'Aucune caméra détectée' 
                : 'Impossible d\'accéder à la caméra';

      setErrorMsg(msg);
      setLoading(false);
      if (addNotification) addNotification(msg, 'error');
    }
  };

  // ====================== ARRÊT TOTAL ======================
  const stopAll = () => {
    if (timeoutRef.current) {
      clearTimeout(timeoutRef.current);
      timeoutRef.current = null;
    }
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
      streamRef.current = null;
    }
    if (videoRef.current) videoRef.current.srcObject = null;

    setCameraActive(false);
    setAutoMode(false);
    setStatus('idle');
    setFaceBox(null);
    setErrorMsg(null);
    setErrorDetails(null);
  };

  // ====================== DESSIN FACE BOX ======================
  const drawFaceBox = (box) => {
    const canvas = overlayCanvasRef.current;
    const video = videoRef.current;
    if (!canvas || !video || !box) return;

    const ctx = canvas.getContext('2d');
    canvas.width = video.clientWidth;
    canvas.height = video.clientHeight;

    const scaleX = canvas.width / video.videoWidth;
    const scaleY = canvas.height / video.videoHeight;

    ctx.strokeStyle = '#16A34A';
    ctx.lineWidth = 3;
    ctx.strokeRect(
      box.x * scaleX,
      box.y * scaleY,
      box.width * scaleX,
      box.height * scaleY
    );
  };

  // ====================== BOUCLE CAPTURE ADAPTATIVE ======================
  const startCaptureLoop = useCallback(() => {
    if (!autoMode || !cameraActive) return;

    const captureFrame = async () => {
      if (!videoRef.current) return;

      try {
        const canvas = document.createElement('canvas');
        canvas.width = videoRef.current.videoWidth || 1280;
        canvas.height = videoRef.current.videoHeight || 720;

        const ctx = canvas.getContext('2d');
        ctx.drawImage(videoRef.current, 0, 0);

        const imageBase64 = canvas.toDataURL('image/jpeg', 0.82);
        const base64Data = imageBase64.split(',')[1];   // Sans préfixe

        setFrameCount(prev => prev + 1);

        const response = await attendanceAPI.recognize(base64Data);
        const data = response?.data || response;
        const confidence = data.confidence || 0;

        if (data.face_box) {
          setFaceBox(data.face_box);
          drawFaceBox(data.face_box);
        }

        if (data.success && data.student) {
          setCapturedImage(imageBase64);
          setRegisteredPhotoUrl(data.registered_photo_url || null);
          setLastDetectionTime(new Date().toLocaleTimeString());
          setLastResult(data);
          setStatus('success');
          setSuccessCount(prev => prev + 1);
          playSound('success');
          addNotification(`${data.student} marqué présent`, 'success');

          setAutoMode(false);
          setTimeout(() => setAutoMode(true), 4500);
        } 
        else if (confidence >= CONFIDENCE_THRESHOLD) {
          setCapturedImage(imageBase64);
          setRegisteredPhotoUrl(data.registered_photo_url || null);
          setStatus('warning');
          setErrorMsg(data.message || `Visage détecté mais confiance faible (${(confidence * 100).toFixed(1)}%)`);
          setErrorCount(prev => prev + 1);
          playSound('warning');

          if (timeoutRef.current) clearTimeout(timeoutRef.current);
          timeoutRef.current = setTimeout(captureFrame, CAPTURE_INTERVAL_FAST);
          return;
        } 
        else {
          setCapturedImage(imageBase64);
          setStatus('error');
          setErrorMsg(data.message || 'Visage non reconnu');
          setErrorCount(prev => prev + 1);
        }
      } catch (err) {
        console.error('[API ERROR]', err);

        const statusCode = err.response?.status;
        const statusText = err.response?.statusText;
        const backendMsg = err.response?.data?.message || err.response?.data?.error || err.message;

        let displayMessage = 'Erreur lors de la reconnaissance';

        if (statusCode) {
          displayMessage = `Erreur API (${statusCode}) : ${backendMsg}`;
        } else if (err.message.includes('CORS') || err.message.includes('Network')) {
          displayMessage = 'Erreur réseau ou CORS : vérifiez le proxy et les autorisations backend';
        }

        setErrorMsg(displayMessage);
        setErrorDetails({
          status: statusCode,
          statusText: statusText,
          backendMessage: backendMsg,
          jsMessage: err.message
        });

        setStatus('error');
        setErrorCount(prev => prev + 1);
      }

      if (timeoutRef.current) clearTimeout(timeoutRef.current);
      timeoutRef.current = setTimeout(captureFrame, CAPTURE_INTERVAL_DEFAULT);
    };

    if (timeoutRef.current) clearTimeout(timeoutRef.current);
    timeoutRef.current = setTimeout(captureFrame, 400);
  }, [autoMode, cameraActive, addNotification, playSound]);

  useEffect(() => {
    if (autoMode && cameraActive) {
      startCaptureLoop();
    }
    return () => {
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
    };
  }, [autoMode, cameraActive, startCaptureLoop]);

  // ====================== CAPTURE MANUELLE ======================
  const handleManualCapture = async () => {
    if (!videoRef.current || loading) return;

    setLoading(true);
    setErrorMsg(null);
    setErrorDetails(null);

    try {
      const canvas = document.createElement('canvas');
      canvas.width = videoRef.current.videoWidth || 1280;
      canvas.height = videoRef.current.videoHeight || 720;
      const ctx = canvas.getContext('2d');
      ctx.drawImage(videoRef.current, 0, 0);

      const imageBase64 = canvas.toDataURL('image/jpeg', 0.85);
      const base64Data = imageBase64.split(',')[1];

      setCapturedImage(imageBase64);

      const response = await attendanceAPI.recognize(base64Data);
      const data = response?.data || response;
      const confidence = data.confidence || 0;

      if (data.success && data.student) {
        setLastResult(data);
        setRegisteredPhotoUrl(data.registered_photo_url);
        setLastDetectionTime(new Date().toLocaleTimeString());
        setStatus('success');
        setSuccessCount(prev => prev + 1);
        playSound('success');
        addNotification(`${data.student} marqué présent`, 'success');
      } else if (confidence >= CONFIDENCE_THRESHOLD) {
        setStatus('warning');
        setErrorMsg(data.message || `Visage détecté mais confiance faible (${(confidence * 100).toFixed(1)}%)`);
        setErrorCount(prev => prev + 1);
      } else {
        setStatus('error');
        setErrorMsg(data.message || 'Visage non reconnu');
        setErrorCount(prev => prev + 1);
      }
    } catch (err) {
      const statusCode = err.response?.status;
      const backendMsg = err.response?.data?.message || err.response?.data?.error || err.message;

      const displayMsg = statusCode 
        ? `Erreur API (${statusCode}) : ${backendMsg}`
        : 'Erreur réseau ou CORS : vérifiez le proxy et les autorisations backend';

      setErrorMsg(displayMsg);
      setErrorDetails({
        status: statusCode,
        backendMessage: backendMsg,
        jsMessage: err.message
      });
      setStatus('error');
      setErrorCount(prev => prev + 1);
    } finally {
      setLoading(false);
    }
  };

  // Placeholder photo enregistrée
  const RegisteredPhoto = () => {
    if (registeredPhotoUrl) {
      return <img src={registeredPhotoUrl} alt="Photo enregistrée" style={styles.photo} />;
    }
    return (
      <div style={styles.placeholder}>
        <div style={styles.silhouette}>Personne</div>
        <p>Photo de référence</p>
      </div>
    );
  };

  // Nettoyage au démontage
  useEffect(() => {
    return () => {
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
      if (streamRef.current) streamRef.current.getTracks().forEach(track => track.stop());
    };
  }, []);

  return (
    <div style={styles.container}>
      <h1 style={styles.title}>Reconnaissance Faciale</h1>

      <div style={styles.videoContainer}>
        <video
          ref={videoRef}
          autoPlay
          playsInline
          muted
          style={styles.video}
          aria-label="Flux vidéo en direct"
        />
        <canvas ref={overlayCanvasRef} style={styles.overlayCanvas} />

        {cameraActive && (
          <div style={{
            ...styles.statusBadge,
            backgroundColor: status === 'success' ? COLORS.success :
                            status === 'warning' ? COLORS.warning :
                            status === 'error' ? COLORS.danger : COLORS.primary
          }}>
            {status === 'success' ? 'Reconnu' :
             status === 'warning' ? 'Confiance faible' :
             status === 'error' ? 'Non reconnu' : 'Analyse en cours'}
          </div>
        )}
      </div>

      <div style={styles.controls}>
        {!cameraActive ? (
          <button
            onClick={startCamera}
            disabled={loading}
            style={styles.btnPrimary}
            aria-label="Démarrer la caméra et le scan automatique"
          >
            Démarrer Auto
          </button>
        ) : (
          <>
            <button
              onClick={handleManualCapture}
              disabled={loading}
              style={styles.btnPrimary}
              aria-label="Capturer une image maintenant"
            >
              {loading ? 'Traitement en cours...' : 'Capturer maintenant'}
            </button>

            <button
              onClick={() => setAutoMode(!autoMode)}
              style={{
                ...styles.btn,
                backgroundColor: autoMode ? COLORS.danger : COLORS.success
              }}
              aria-label={autoMode ? "Arrêter le scan automatique" : "Démarrer le scan automatique"}
            >
              {autoMode ? 'Arrêter Auto' : 'Démarrer Auto'}
            </button>

            <button
              onClick={stopAll}
              style={styles.btnDanger}
              aria-label="Fermer complètement la caméra"
            >
              Fermer Caméra
            </button>
          </>
        )}
      </div>

      {/* Comparaison des photos */}
      {capturedImage && (
        <div style={styles.comparison}>
          <div style={styles.photoGrid}>
            <div>
              <h3 style={styles.label}>Photo Capturée</h3>
              <img src={capturedImage} alt="Capture" style={styles.photo} />
            </div>
            <div>
              <h3 style={styles.label}>Photo de Référence</h3>
              <RegisteredPhoto />
            </div>
          </div>
        </div>
      )}

      {/* Résultat succès */}
      {lastResult && status === 'success' && (
        <div style={styles.successBox}>
          <h3>Présence enregistrée</h3>
          <p><strong>Nom :</strong> {lastResult.student}</p>
          <p><strong>Email :</strong> {lastResult.email || 'N/A'}</p>
          <p><strong>Confiance :</strong> {(lastResult.confidence * 100).toFixed(1)}%</p>
          <p><strong>ID Présence :</strong> {lastResult.attendance_id}</p>
          <p><strong>Heure :</strong> {lastDetectionTime}</p>
        </div>
      )}

      {/* Messages d'erreur */}
      {errorMsg && (
        <div style={status === 'warning' ? styles.warningBox : styles.errorBox}>
          {errorMsg}
          {errorDetails && (
            <div style={styles.errorDetails}>
              <small>
                Code : {errorDetails.status || '—'}<br />
                Message : {errorDetails.backendMessage || errorDetails.jsMessage}
              </small>
            </div>
          )}
        </div>
      )}

      {/* Statistiques */}
      <div style={styles.stats}>
        <div>Succès : <strong style={{ color: COLORS.success }}>{successCount}</strong></div>
        <div>Échecs : <strong style={{ color: COLORS.danger }}>{errorCount}</strong></div>
        <div>Frames traités : <strong>{frameCount}</strong></div>
        <div>Dernière détection : <strong>{lastDetectionTime || '—'}</strong></div>
      </div>

      {/* Debug */}
      <div style={styles.debugBox}>
        <h4>Informations de débogage</h4>
        <p><strong>Caméra :</strong> {cameraActive ? 'Active' : 'Inactive'}</p>
        <p><strong>Mode Auto :</strong> {autoMode ? 'Activé' : 'Désactivé'}</p>
        <p><strong>Statut :</strong> {status}</p>
      </div>

      <style>{`
        @keyframes fadeIn {
          from { opacity: 0; transform: translateY(10px); }
          to { opacity: 1; transform: translateY(0); }
        }
      `}</style>
    </div>
  );
};

const styles = {
  container: { 
    padding: '40px 20px', 
    maxWidth: '1200px', 
    margin: '0 auto', 
    fontFamily: 'system-ui, Arial, sans-serif',
    backgroundColor: COLORS.background 
  },
  title: { 
    textAlign: 'center', 
    fontSize: '2rem', 
    fontWeight: '700', 
    color: COLORS.text, 
    marginBottom: '32px' 
  },

  videoContainer: { 
    position: 'relative', 
    borderRadius: '12px', 
    overflow: 'hidden', 
    boxShadow: '0 10px 30px rgba(0,0,0,0.12)', 
    background: '#000', 
    marginBottom: '30px' 
  },
  video: { width: '100%', display: 'block' },
  overlayCanvas: { 
    position: 'absolute', 
    top: 0, 
    left: 0, 
    width: '100%', 
    height: '100%', 
    pointerEvents: 'none' 
  },

  statusBadge: {
    position: 'absolute',
    top: '20px',
    right: '20px',
    color: 'white',
    padding: '10px 20px',
    borderRadius: '30px',
    fontWeight: '600',
    fontSize: '0.95rem'
  },

  controls: { 
    display: 'flex', 
    gap: '12px', 
    flexWrap: 'wrap', 
    marginBottom: '32px' 
  },
  btn: { 
    flex: 1, 
    padding: '16px 20px', 
    border: 'none', 
    borderRadius: '8px', 
    color: 'white', 
    fontWeight: '600', 
    cursor: 'pointer', 
    fontSize: '1.02rem',
    transition: 'background-color 0.2s'
  },
  btnPrimary: { backgroundColor: COLORS.primary },
  btnDanger: { backgroundColor: COLORS.danger },

  comparison: { margin: '30px 0' },
  photoGrid: { display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '24px' },
  label: { fontSize: '1.1rem', fontWeight: '600', marginBottom: '12px', color: COLORS.text },
  photo: { width: '100%', borderRadius: '10px', border: `2px solid ${COLORS.border}` },

  placeholder: {
    width: '100%',
    height: '320px',
    backgroundColor: '#F1F5F9',
    border: `2px dashed ${COLORS.border}`,
    borderRadius: '10px',
    display: 'flex',
    flexDirection: 'column',
    alignItems: 'center',
    justifyContent: 'center',
    color: COLORS.gray
  },
  silhouette: { fontSize: '4.8rem', opacity: 0.35, marginBottom: '12px' },

  successBox: { 
